package echo

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

func tryFind(t *testing.T, e *Echo, method, path string) (out string) {
	defer func() {
		if r := recover(); r != nil {
			out = fmt.Sprintf("PANIC: %v", r)
		}
	}()
	c := e.NewContext(httptest.NewRequest(method, "/", nil), httptest.NewRecorder())
	e.router.Find(method, path, c)
	return fmt.Sprintf("handler=%v path=%q pnames=%v pvalues=%v", c.Handler() != nil, c.Path(), c.ParamNames(), c.ParamValues())
}

func tryAdd(t *testing.T, e *Echo, method, path string) (out string) {
	defer func() {
		if r := recover(); r != nil {
			out = fmt.Sprintf("PANIC: %v", r)
		}
	}()
	e.router.Add(method, path, func(c Context) error { return nil })
	return "ok"
}

func TestZZTmpRouterProbe(t *testing.T) {
	routeSets := map[string][]string{
		"none":  {},
		"root":  {"/"},
		"slash": {"/", "/a"},
		"param": {"/:id", "/a"},
		"any":   {"/a/*", "/a"},
		"multi": {"/", "/a", "/a/b", "/:id", "/:id/x", "/a/*"},
	}
	paths := []string{"", "/", "//", "///", "a", "a/b", "/a", "/a/", "/a/b", "/x", "/x/y", "/a/b/c", "/%2F", "*", ":", ":/", "/*"}
	for rn, routes := range routeSets {
		for _, r := range routes {
			e := NewEcho()
			_ = e
		}
		_ = rn
	}
	for rn, routes := range routeSets {
		for _, p := range paths {
			e := New()
			for _, r := range routes {
				if res := tryAdd(t, e, http.MethodGet, r); res != "ok" {
					t.Logf("ADD[%s] %q -> %s", rn, r, res)
				}
			}
			res := tryFind(t, e, http.MethodGet, p)
			t.Logf("FIND[%s] routes=%v path=%q -> %s", rn, routes, p, res)
		}
	}
}

func TestZZTmpRouterAddProbe(t *testing.T) {
	paths := []string{"", "/", "//", "a", "*", "/*", "/:", "/:a", ":", "/a/:", "/a/*", "/*/a", "/a/*/b", "/%2F", "/a b"}
	for _, p := range paths {
		e := New()
		res := tryAdd(t, e, http.MethodGet, p)
		t.Logf("ADD %q -> %s", p, res)
	}
}
