package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"testing"
	"time"
)

func randPath2(rnd *rand.Rand) string {
	alphabet := []byte("/:*.ab ")
	n := rnd.Intn(10)
	b := make([]byte, n)
	for i := range b {
		b[i] = alphabet[rnd.Intn(len(alphabet))]
	}
	return string(b)
}

func TestZZTmpFuzzHang(t *testing.T) {
	rnd := rand.New(rand.NewSource(99))
	for iter := 0; iter < 20000; iter++ {
		nRoutes := rnd.Intn(6)
		routes := make([]string, nRoutes)
		for i := range routes {
			routes[i] = randPath2(rnd)
		}
		path := randPath2(rnd)
		done := make(chan bool, 1)
		panicked := make(chan interface{}, 1)
		go func() {
			defer func() {
				if rec := recover(); rec != nil {
					panicked <- rec
				}
			}()
			e := New()
			r := e.router
			for _, rt := range routes {
				r.Add(http.MethodGet, rt, func(c Context) error { return nil })
			}
			c := e.NewContext(nil, nil).(*context)
			r.Find(http.MethodGet, path, c)
			done <- true
		}()
		select {
		case <-done:
		case rec := <-panicked:
			t.Fatalf("PANIC iter=%d routes=%q path=%q: %v", iter, routes, path, rec)
		case <-time.After(2 * time.Second):
			t.Fatalf("HANG iter=%d routes=%q path=%q", iter, routes, path)
		}
	}
	fmt.Println("fuzz done")
}
EOF
timeout 900 go test -run 'ZZTmpFuzzHang' -v -timeout 800s . 2>&1 | tail -20

