func randSeg(rnd *rand.Rand) string {
	switch rnd.Intn(6) {
	case 0:
		return "a"
	case 1:
		return "b"
	case 2:
		return ":x"
	case 3:
		return ":y"
	case 4:
		return "*"
	default:
		return ""
	}
}

func randRoute(rnd *rand.Rand) string {
	n := rnd.Intn(4) + 1
	segs := make([]string, n)
	for i := range segs {
		segs[i] = randSeg(rnd)
	}
	return "/" + strings.Join(segs, "/")
}

func TestZZTmpFuzzSegments(t *testing.T) {
	rnd := rand.New(rand.NewSource(2024))
	for iter := 0; iter < 300000; iter++ {
		nRoutes := rnd.Intn(4) + 1
		routes := make([]string, nRoutes)
		for i := range routes {
			routes[i] = randRoute(rnd)
		}
		path := randRoute(rnd)
		done := make(chan interface{}, 1)
		go func(routes []string, path string) {
			defer func() {
				if rec := recover(); rec != nil {
					done <- rec
					return
				}
				done <- nil
			}()
			e := New()
			r := e.router
			for _, rt := range routes {
				r.Add(http.MethodGet, rt, func(c Context) error { return nil })
			}
			c := e.NewContext(nil, nil).(*context)
			r.Find(http.MethodGet, path, c)
			if c.handler == nil {
				done <- fmt.Errorf("nil handler")
				return
			}
			c.handler(c)
		}(routes, path)
		select {
		case rec := <-done:
			if rec != nil {
				t.Fatalf("FAIL iter=%d routes=%q path=%q: %v", iter, routes, path, rec)
			}
		case <-time.After(5 * time.Second):
			t.Fatalf("HANG iter=%d routes=%q path=%q", iter, routes, path)
		}
	}
	fmt.Println("ok")
}
