package echo

import (
	"net/http"
	"testing"
)

// helper: middleware that logs its name into a shared log slice stored in context
func zzLogMW(name string, log *[]string) MiddlewareFunc {
	return func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			*log = append(*log, name)
			return next(c)
		}
	}
}

func TestZZTmpSiblingGroupsSamePath(t *testing.T) {
	e := New()
	log := []string{}

	g1 := e.Group("/api")
	g1.Use(zzLogMW("m1", &log))
	g1.GET("/one", func(c Context) error { return c.String(http.StatusOK, "one") })

	g2 := e.Group("/api")
	g2.Use(zzLogMW("m2", &log))
	g2.GET("/two", func(c Context) error { return c.String(http.StatusOK, "two") })

	log = log[:0]
	_, _ = request(http.MethodGet, "/api/one", e)
	t.Logf("GET /api/one -> %v (want [m1])", log)

	log = log[:0]
	_, _ = request(http.MethodGet, "/api/two", e)
	t.Logf("GET /api/two -> %v (want [m2])", log)

	log = log[:0]
	_, _ = request(http.MethodGet, "/api/unknown", e)
	t.Logf("GET /api/unknown -> %v", log)

	// assertions
	log = log[:0]
	_, _ = request(http.MethodGet, "/api/one", e)
	if len(log) != 1 || log[0] != "m1" {
		t.Errorf("GET /api/one middleware = %v, want [m1]", log)
	}
	log = log[:0]
	_, _ = request(http.MethodGet, "/api/two", e)
	if len(log) != 1 || log[0] != "m2" {
		t.Errorf("GET /api/two middleware = %v, want [m2]", log)
	}
}

func TestZZTmpNestedGroupSamePath(t *testing.T) {
	e := New()
	log := []string{}

	g := e.Group("/api")
	g.Use(zzLogMW("parent", &log))
	sg := g.Group("/api")
	sg.Use(zzLogMW("child", &log))
	sg.GET("/x", func(c Context) error { return c.String(http.StatusOK, "x") })

	log = log[:0]
	_, _ = request(http.MethodGet, "/api/api/x", e)
	t.Logf("GET /api/api/x -> %v (want [parent child])", log)
	if len(log) != 2 || log[0] != "parent" || log[1] != "child" {
		t.Errorf("nested same path middleware = %v, want [parent child]", log)
	}
}

func TestZZTmpGroupMiddlewareInCtor(t *testing.T) {
	e := New()
	log := []string{}

	g1 := e.Group("/api", zzLogMW("m1", &log))
	g1.GET("/one", func(c Context) error { return c.String(http.StatusOK, "one") })

	g2 := e.Group("/api", zzLogMW("m2", &log))
	g2.GET("/two", func(c Context) error { return c.String(http.StatusOK, "two") })

