package echo

import (
	"net/http"
	"testing"
)

// helper: middleware that logs its name into a shared log slice stored in context
func zzLogMW(name string, log *[]string) MiddlewareFunc {
	return func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			*log = append(*log, name)
			return next(c)
		}
	}
}

func zzCheck(t *testing.T, e *Echo, log *[]string, method, path string, want []string) {
	t.Helper()
	*log = (*log)[:0]
	_, _ = request(method, path, e)
	got := append([]string{}, (*log)...)
	if len(got) != len(want) {
		t.Errorf("%s %s: middleware = %v, want %v", method, path, got, want)
		return
	}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("%s %s: middleware = %v, want %v", method, path, got, want)
			return
		}
	}
}

func TestZZTmpSiblingGroupsSamePath(t *testing.T) {
	e := New()
	log := []string{}

	g1 := e.Group("/api")
	g1.Use(zzLogMW("m1", &log))
	g1.GET("/one", func(c Context) error { return c.String(http.StatusOK, "one") })

	g2 := e.Group("/api")
	g2.Use(zzLogMW("m2", &log))
	g2.GET("/two", func(c Context) error { return c.String(http.StatusOK, "two") })

	zzCheck(t, e, &log, http.MethodGet, "/api/one", []string{"m1"})
	zzCheck(t, e, &log, http.MethodGet, "/api/two", []string{"m2"})
	zzCheck(t, e, &log, http.MethodGet, "/api/unknown", []string{"m2"})
}

